examples.template:
Column(
    modifier = Modifier.widthIn(max = {{maxWidth}}.dp),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
) {
    MonarchSearchBar(
        query = query,
        onQueryChange = { query = it },
        onSearch = {},
        placeholder = {{placeholder}},
    )
    MonarchText(
        text = "${matches.size} ${if (matches.size == 1) "result" else "results"}" +
            if (query.isEmpty()) "" else " for \u201C$query\u201D",
        style = MonarchTextStyle.Caption,
    )
}

